steps.script:
function transform(ctx) {
  var MAP = { "校园网": "NUIST", "移动": "CMCC", "电信": "ChinaNet", "联通": "Unicom" };
  var isp = (ctx.isp || "").trim();
  var domain = isp ? (MAP[isp] !== undefined ? MAP[isp] : isp) : "NUIST";
  return { form_username: url_encode(ctx.username || ""), form_password: url_encode(base64_encode(ctx.password || "")), domain_val: url_encode(domain) };
}
